def summarize(rows: list[dict]) -> list[dict]:
    groups = {}
    for row in rows:
        if row.get("enabled") is not True:
            continue
        owner = row.get("owner")
        if not isinstance(owner, str):
            continue
        amount = row.get("amount")
        try:
            amount_val = float(amount)
        except (ValueError, TypeError):
            continue
        if owner not in groups:
            groups[owner] = {"count": 0, "total": 0.0}
        groups[owner]["count"] += 1
        groups[owner]["total"] += amount_val

    result = []
    for owner, data in groups.items():
        result.append({
            "owner": owner,
            "count": data["count"],
            "total": round(data["total"], 2)
        })

    result.sort(key=lambda x: (-x["total"], x["owner"]))
    return result

